<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class HrDashboardController extends Controller{
 public function index(){ $today=today();$soon=$today->copy()->addDays(90);$staffing=DB::table('staffing_positions as sp')->join('staff_positions as p','p.id','=','sp.position_id')->leftJoin('academic_departments as d','d.id','=','sp.academic_department_id')->where('sp.active',1)->select('sp.*','p.name as position_name','d.name as department_name')->get()->map(function($x){$x->occupied=(float)DB::table('employee_employments')->where(['position_id'=>$x->position_id,'status'=>'active'])->when($x->academic_department_id,fn($q)=>$q->where('academic_department_id',$x->academic_department_id),fn($q)=>$q->whereNull('academic_department_id'))->sum('rate');$x->vacant=max(0,(float)$x->planned_rates-$x->occupied);return $x;});$alerts=collect();DB::table('employee_attestations as a')->join('employees as e','e.id','=','a.employee_id')->where('e.active',1)->whereNotNull('a.next_attestation_on')->whereBetween('a.next_attestation_on',[$today,$soon])->select('e.id','e.last_name','e.first_name','a.next_attestation_on as due')->get()->each(fn($x)=>$alerts->push((object)['employee_id'=>$x->id,'name'=>$x->last_name.' '.$x->first_name,'type'=>'Аттестация','due'=>$x->due]));DB::table('employee_trainings as t')->join('employees as e','e.id','=','t.employee_id')->where('e.active',1)->whereNotNull('t.valid_until')->whereBetween('t.valid_until',[$today,$soon])->select('e.id','e.last_name','e.first_name','t.valid_until as due')->get()->each(fn($x)=>$alerts->push((object)['employee_id'=>$x->id,'name'=>$x->last_name.' '.$x->first_name,'type'=>'Истекает документ об обучении','due'=>$x->due]));$withoutEducation=DB::table('employees as e')->leftJoin('employee_educations as ed','ed.employee_id','=','e.id')->where('e.active',1)->whereNull('ed.id')->select('e.id','e.last_name','e.first_name')->get();$withoutEmployment=DB::table('employees as e')->leftJoin('employee_employments as em',fn($j)=>$j->on('em.employee_id','=','e.id')->where('em.status','=','active'))->where('e.active',1)->whereNull('em.id')->select('e.id','e.last_name','e.first_name')->get();return view('admin.hr.dashboard',compact('staffing','alerts','withoutEducation','withoutEmployment'));}
 public function staffing(Request $r){$d=$r->validate(['position_id'=>'required|exists:staff_positions,id','academic_department_id'=>'nullable|exists:academic_departments,id','planned_rates'=>'required|numeric|min:0.01|max:100','valid_from'=>'nullable|date','valid_until'=>'nullable|date|after_or_equal:valid_from','note'=>'nullable|string|max:3000']);DB::table('staffing_positions')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Позиция штатного расписания добавлена');}
}